  let attempts=0;const deniedDirectory=join(root,"denied"),denied=openRecordStore(deniedDirectory,{publication:(_plan:any,_write:()=>void)=>{attempts++;return false;}}as any);try{for(let iteration=0;iteration<3;iteration++){for(const record of row.records){const computed=Buffer.from(record.value);denied.put(record.key,computed);expect(Buffer.from(denied.get(record.key)!).toString()).toBe(record.value);}denied.flush();expect(denied.stats.records).toBe(0);expect(await rawPromises.readdir(deniedDirectory)).toEqual([]);}expect(attempts).toBe(3);}finally{denied.close();}
